      <div className="fixed inset-0 pointer-events-none bg-[radial-gradient(ellipse_at_center,rgba(249,140,6,0.05)_0%,transparent_70%)] z-0"></div>

      {/* ===== Sidebar (Cabin Control Panel) ===== */}
