import { useState } from 'react';
import type { GameType } from '../types';

interface PathInputProps {
  game: GameType;
  onScan: (path: string) => void;
  loading: boolean;
  error: string | null;
  onBack: () => void;
}

const defaultPaths: Record<GameType, string> = {
  ets2: '/home/' + 'USER' + '/.local/share/Euro Truck Simulator 2/profiles/',
  ats: '/home/' + 'USER' + '/.local/share/American Truck Simulator/profiles/',
};

export default function PathInput({ game, onScan, loading, error, onBack }: PathInputProps) {
  const [path, setPath] = useState(defaultPaths[game]);

  return (
    <div className="min-h-screen w-full flex flex-col p-6 bg-background-dark text-text-main font-body antialiased relative overflow-hidden selection:bg-primary selection:text-black">
      {/* Background Scanlines Effect */}
      <div className="absolute inset-0 z-0 h-full w-full scanlines-overlay opacity-30 mix-blend-overlay"></div>

      {/* Header */}
      <div className="relative z-20 flex items-center justify-between p-4 bg-background-dark/80 backdrop-blur-md border border-white/5 rounded-2xl max-w-5xl w-full mx-auto mt-6">
        <button
          onClick={onBack}
          className="text-white hover:text-primary transition-colors flex h-10 w-10 shrink-0 items-center justify-center rounded-lg active:bg-surface/50 cursor-pointer"
        >
          <span className="material-symbols-outlined text-3xl">chevron_left</span>
        </button>
        <h2 className="text-white text-xl md:text-2xl font-display font-bold leading-tight tracking-wider flex-1 text-center pr-10 uppercase">
          Locate Terminal
        </h2>
      </div>

      <div className="flex-1 flex flex-col items-center justify-center w-full mx-auto relative z-10 -mt-10">
        <div className="w-full max-w-4xl glass-panel p-8 md:p-12 rounded-3xl shadow-2xl relative overflow-hidden">
          {/* Subtle decoration inside card */}
          <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-transparent via-primary/50 to-transparent"></div>

          {/* Central Radar Illustration */}
          <div className="flex flex-col items-center justify-center py-6 opacity-80 mb-6">
            <div className="relative size-32 mb-4 flex items-center justify-center">
              <div className="absolute inset-0 rounded-full border border-primary/20 animate-pulse"></div>
              <div className="absolute inset-4 rounded-full border border-primary/10"></div>
              <div className="h-full w-[1px] bg-gradient-to-b from-transparent via-primary/50 to-transparent absolute left-1/2 -translate-x-1/2"></div>
              <div className="w-full h-[1px] bg-gradient-to-r from-transparent via-primary/50 to-transparent absolute top-1/2 -translate-y-1/2"></div>
              <div className="relative z-10 bg-surface/80 p-4 rounded-full backdrop-blur-sm border border-white/5 shadow-neon">
                <span className="material-symbols-outlined text-primary text-5xl">{game === 'ets2' ? 'folder_special' : 'folder_open'}</span>
              </div>
            </div>
            <p className="text-primary font-mono text-sm uppercase tracking-[0.3em] font-bold">
              {game === 'ets2' ? 'Euro Truck 2' : 'American Truck'}
            </p>
          </div>

          <label className="block text-text-muted font-display font-bold uppercase tracking-wider text-sm mb-3 ml-1">
            System Path
          </label>

          <div className="flex flex-col gap-5">
            <div className="relative group w-full">
              <div className="absolute inset-y-0 left-0 flex items-center pl-5 pointer-events-none text-primary">
                <span className="material-symbols-outlined text-2xl">terminal</span>
              </div>
              <input
                type="text"
                value={path}
                onChange={(e) => setPath(e.target.value)}
                placeholder="Enter path..."
                className="block w-full rounded-2xl border border-white/10 bg-[#0B0E14] py-5 pl-14 pr-6 text-text-main font-mono text-base md:text-lg placeholder-text-muted focus:border-primary focus:ring-1 focus:ring-primary focus:shadow-neon transition-all duration-300"
              />
            </div>

            <button
              onClick={() => onScan(path)}
              disabled={loading || !path.trim()}
              className="w-full bg-primary hover:bg-orange-500 active:scale-[0.98] text-black font-display font-bold text-xl py-5 rounded-2xl shadow-neon transition-all duration-300 flex items-center justify-center group relative overflow-hidden cursor-pointer disabled:opacity-50 disabled:cursor-not-allowed disabled:shadow-none"
            >
              {!loading && (
                <span className="absolute inset-0 w-full h-full bg-gradient-to-r from-transparent via-white/30 to-transparent -translate-x-full group-hover:animate-[shimmer_1.5s_infinite]"></span>
              )}
              {loading ? (
                <>
                  <span className="material-symbols-outlined mr-3 text-2xl animate-spin">data_usage</span>
                  SCANNING...
                </>
              ) : (
                <>
                  <span className="material-symbols-outlined mr-3 text-2xl">radar</span>
                  ENGAGE SCAN
                </>
              )}
            </button>
          </div>
          
          {/* Default Path Hint */}
          <div className="mt-8">
            <p className="text-xs text-text-muted font-mono uppercase tracking-wider mb-2">Default Directory:</p>
            <div className="bg-[#0B0E14] border border-white/5 rounded-xl p-3 flex items-center text-sm font-mono text-text-muted/80 overflow-x-auto no-scrollbar">
              <span className="text-primary mr-2">~</span>
              {defaultPaths[game].replace('/home/USER', '')}
            </div>
          </div>

          {/* Error Message */}
          {error && (
            <div className="mt-6 bg-red-900/20 border border-red-500/30 rounded-2xl px-5 py-4 text-red-400 text-sm md:text-base flex items-center gap-4 font-body animate-slide-in-left shadow-lg">
              <span className="material-symbols-outlined text-2xl">error</span>
              <span className="leading-snug">{error}</span>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
