import { useState } from 'react';
import type { GameData } from '../../types';

interface UserEditorProps {
  data: GameData;
  onChange: (updates: Partial<GameData>) => void;
}

const skillInfo = [
  { key: 'adr', label: 'ADR (Hazardous)', icon: '☣️', desc: 'Muatan berbahaya' },
  { key: 'long_dist', label: 'Long Distance', icon: '🛣️', desc: 'Jarak jauh' },
  { key: 'heavy', label: 'Heavy Cargo', icon: '🏋️', desc: 'Muatan berat / bernilai tinggi' },
  { key: 'fragile', label: 'Fragile Cargo', icon: '📦', desc: 'Muatan rapuh' },
  { key: 'urgent', label: 'Just-in-Time', icon: '⏰', desc: 'Pengiriman tepat waktu' },
  { key: 'mechanical', label: 'Eco Driving', icon: '🌿', desc: 'Mengemudi hemat bahan bakar' },
];

const xpPresets = [
  { label: '5K XP', value: 5_000 },
  { label: '50K XP', value: 50_000 },
  { label: '200K XP', value: 200_000 },
  { label: '500K XP', value: 500_000 },
  { label: '1M XP', value: 1_000_000 },
  { label: '5M XP', value: 5_000_000 },
];

export default function UserEditor({ data, onChange }: UserEditorProps) {
  const [xp, setXp] = useState(data.experiencePoints.toString());

  const handleXpChange = (value: string) => {
    setXp(value);
    const num = parseInt(value, 10);
    if (!isNaN(num) && num >= 0) {
      onChange({ experiencePoints: num });
    }
  };

  const setXpTo = (value: number) => {
    setXp(value.toString());
    onChange({ experiencePoints: value });
  };

  const handleSkillChange = (key: string, value: number) => {
    const clamped = Math.min(6, Math.max(0, value));
    onChange({
      skills: { ...data.skills, [key]: clamped },
    });
  };

  const setAllSkills = (value: number) => {
    const clamped = Math.min(6, Math.max(0, value));
    const newSkills = Object.fromEntries(
      skillInfo.map((s) => [s.key, clamped])
    );
    onChange({ skills: newSkills as GameData['skills'] });
  };

  return (
    <div className="space-y-10 animate-fade-in">
      {/* XP Section */}
      <div className="mb-6">
        <h2 className="text-2xl md:text-3xl font-display font-bold text-white tracking-widest uppercase mb-2 flex items-center gap-3">
          <span className="material-symbols-outlined text-primary text-3xl">star</span>
          Experience Override
        </h2>
        <div className="flex items-center gap-4">
          <div className="h-px bg-gradient-to-r from-primary to-transparent w-32"></div>
          <p className="text-primary font-mono text-xs tracking-[0.2em] uppercase">Telemetry Level Injector</p>
        </div>
      </div>

      <div className="glass-panel rounded-3xl p-8 sm:p-12 border-t-2 border-t-primary relative overflow-hidden group">
        <label className="block text-text-muted font-mono text-xs mb-3 tracking-[0.2em] uppercase relative z-10">
          Total Experience Entry
        </label>
        <div className="relative group/input z-10">
          <input
            type="number"
            value={xp}
            onChange={(e) => handleXpChange(e.target.value)}
            min="0"
            className="w-full bg-surface-dark border border-white/10 rounded-xl px-6 py-5 
                       text-primary text-3xl sm:text-4xl font-display font-bold shadow-inner
                       focus:outline-none focus:border-primary focus:ring-1 focus:ring-primary/50
                       transition-all group-hover/input:border-white/20"
          />
          <span className="absolute right-6 top-1/2 -translate-y-1/2 text-primary/30 text-2xl font-bold pointer-events-none uppercase font-mono">XP</span>
          
           {/* Corner decorations */}
           <div className="absolute top-0 left-0 w-2 h-2 border-t border-l border-white/30 rounded-tl-xl pointer-events-none group-focus-within/input:border-primary"></div>
           <div className="absolute bottom-0 right-0 w-2 h-2 border-b border-r border-white/30 rounded-br-xl pointer-events-none group-focus-within/input:border-primary"></div>
        </div>

        {/* XP Presets */}
        <div className="mt-10 relative z-10">
          <div className="flex items-center gap-2 mb-4">
             <span className="material-symbols-outlined text-primary text-sm">settings_input_component</span>
             <p className="text-xs text-text-muted font-mono tracking-widest uppercase">Quick Injection</p>
          </div>
          <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-3">
            {xpPresets.map((preset) => (
              <button
                key={preset.label}
                onClick={() => setXpTo(preset.value)}
                className="bg-surface border border-white/5 text-text-muted text-sm font-mono tracking-wider 
                           py-3 px-4 rounded-lg hover:border-primary/50 hover:text-primary hover:bg-primary/10
                           transition-all duration-300 cursor-pointer active:scale-95 text-center flex flex-col items-center gap-1 group/btn"
              >
                <span className="material-symbols-outlined text-[16px] opacity-0 h-0 group-hover/btn:opacity-100 group-hover/btn:h-auto transition-all">add_circle</span>
                {preset.label}
              </button>
            ))}
          </div>
        </div>
      </div>

      {/* Skills Section */}
      <div className="pt-4 border-t border-white/5">
        <div className="flex flex-col xl:flex-row xl:items-center justify-between gap-6 mb-8 mt-4">
          <div>
            <h2 className="text-2xl md:text-3xl font-display font-bold text-white tracking-widest uppercase mb-2 flex items-center gap-3">
              <span className="material-symbols-outlined text-blue-500 text-3xl">build</span>
              Capability Matrix
            </h2>
            <div className="flex items-center gap-4">
              <div className="h-px bg-gradient-to-r from-blue-500 to-transparent w-32"></div>
              <p className="text-blue-500 font-mono text-xs tracking-[0.2em] uppercase">Driver Skill Nodes (Max Lvl 6)</p>
            </div>
          </div>
          
          <div className="flex gap-4">
            <button
              onClick={() => setAllSkills(0)}
              className="text-xs font-mono font-bold bg-surface border border-white/10 text-white/50 px-6 py-3 rounded-xl
                         hover:border-danger/40 hover:text-danger hover:bg-danger/10 transition-all cursor-pointer active:scale-95 tracking-widest uppercase flex items-center gap-2"
            >
              <span className="material-symbols-outlined text-[16px]">device_reset</span> Disable All
            </button>
            <button
              onClick={() => setAllSkills(6)}
              className="text-xs font-mono font-bold bg-blue-500/10 border border-blue-500/30 text-blue-500 px-8 py-3 rounded-xl
                         hover:bg-blue-500/20 hover:border-blue-500/50 hover:shadow-[0_0_15px_rgba(59,130,246,0.2)] transition-all cursor-pointer active:scale-95 tracking-widest uppercase flex items-center gap-2"
            >
              <span className="material-symbols-outlined text-[16px]">upload</span> Maximize All
            </button>
          </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-5">
          {skillInfo.map((skill) => {
            const value = data.skills[skill.key as keyof typeof data.skills];
            return (
              <div key={skill.key} className="glass-panel rounded-2xl p-6 border-l-4 border-l-blue-500/30 hover:border-l-blue-500 transition-all duration-300 group">
                <div className="flex items-start gap-4 mb-6">
                  <div className="w-12 h-12 rounded-xl bg-surface-dark flex items-center justify-center border border-white/5 group-hover:border-blue-500/30">
                    <span className="text-2xl drop-shadow-md">{skill.icon}</span>
                  </div>
                  <div className="flex-1 min-w-0">
                    <h4 className="text-lg font-display font-bold text-white tracking-wider uppercase mb-1 truncate">{skill.label}</h4>
                    <p className="text-[10px] text-text-muted font-mono tracking-widest uppercase truncate">{skill.desc}</p>
                  </div>
                  <div className="bg-surface-dark px-3 py-1 rounded-lg border border-white/5 flex items-baseline">
                    <span className="text-2xl font-display font-bold text-white drop-shadow-neon">{value}</span>
                    <span className="text-[10px] text-white/30 font-mono ml-1">/ 6</span>
                  </div>
                </div>

                {/* Skill Level Buttons (HUD blocks) */}
                <div className="flex gap-1.5 p-1.5 bg-surface-dark rounded-xl border border-white/5">
                  {Array.from({ length: 7 }, (_, i) => (
                    <button
                      key={i}
                      onClick={() => handleSkillChange(skill.key, i)}
                      className={`flex-1 py-2 sm:py-3 rounded-lg text-sm font-mono font-bold transition-all duration-300 cursor-pointer
                                 ${value === i
                                   ? 'bg-blue-500 text-white shadow-[0_0_10px_rgba(59,130,246,0.6)]'
                                   : value > i
                                     ? 'bg-blue-500/20 text-blue-400 border border-blue-500/10'
                                     : 'bg-transparent text-white/20 hover:bg-white/5 hover:text-white border border-transparent'
                                 }`}
                    >
                      {i}
                    </button>
                  ))}
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}
