import { useState } from 'react';
import type { GameData } from '../../types';

interface ProfileEditorProps {
  data: GameData;
  onChange: (updates: Partial<GameData>) => void;
}

const presets = [
  { label: '+€100K', value: 100_000 },
  { label: '+€500K', value: 500_000 },
  { label: '+€1M', value: 1_000_000 },
  { label: '+€5M', value: 5_000_000 },
  { label: '+€10M', value: 10_000_000 },
  { label: '+€100M', value: 100_000_000 },
];

export default function ProfileEditor({ data, onChange }: ProfileEditorProps) {
  const [money, setMoney] = useState(data.money.toString());

  const handleMoneyChange = (value: string) => {
    setMoney(value);
    const num = parseInt(value, 10);
    if (!isNaN(num)) {
      onChange({ money: num });
    }
  };

  const addMoney = (amount: number) => {
    const current = parseInt(money, 10) || 0;
    const newVal = current + amount;
    setMoney(newVal.toString());
    onChange({ money: newVal });
  };

  return (
    <div className="space-y-8 animate-fade-in">
      <div className="mb-6">
        <h2 className="text-2xl md:text-3xl font-display font-bold text-white tracking-widest uppercase mb-2 flex items-center gap-3">
          <span className="material-symbols-outlined text-primary text-3xl">account_balance</span>
          Financial Module
        </h2>
        <div className="flex items-center gap-4">
          <div className="h-px bg-gradient-to-r from-success to-transparent w-32"></div>
          <p className="text-success font-mono text-xs tracking-[0.2em] uppercase">Company Funds Override</p>
        </div>
      </div>

      <div className="glass-panel rounded-3xl p-8 sm:p-12 border-t-2 border-t-success relative overflow-hidden group">
        
        {/* Decorative Grid Background */}
        <div className="absolute inset-0 bg-[url('data:image/svg+xml;base64,PHN2ZyB3aWR0aD0iNDAiIGhlaWdodD0iNDAiIHhtbG5zPSJodHRwOi8vd3d3LnczLm9yZy8yMDAwL3N2ZyI+PGNpcmNsZSBjeD0iMjAiIGN5PSIyMCIgcj0iMSIgZmlsbD0icmdiYSgyNTUsMjU1LDI1NSwwLjA1KSIvPjwvc3ZnPg==')] opacity-20 pointer-events-none mix-blend-overlay"></div>
        <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:opacity-20 transition-opacity">
           <span className="material-symbols-outlined text-9xl text-success">euro</span>
        </div>

        <label className="block text-text-muted font-mono text-xs mb-3 tracking-[0.2em] uppercase relative z-10">
          Target Balance Entry
        </label>
        <div className="flex gap-4 relative z-10">
          <div className="relative flex-1 group/input">
            <span className="absolute left-6 top-1/2 -translate-y-1/2 text-success text-2xl font-bold font-mono">€</span>
            <input
              type="number"
              value={money}
              onChange={(e) => handleMoneyChange(e.target.value)}
              className="w-full bg-surface-dark border border-white/10 rounded-xl pl-14 pr-6 py-5 
                         text-white text-3xl sm:text-4xl font-display font-bold shadow-inner
                         focus:outline-none focus:border-success focus:ring-1 focus:ring-success/50
                         transition-all group-hover/input:border-white/20"
            />
            
            {/* Corner decorations for input */}
            <div className="absolute top-0 left-0 w-2 h-2 border-t border-l border-white/30 rounded-tl-xl pointer-events-none group-focus-within/input:border-success"></div>
            <div className="absolute bottom-0 right-0 w-2 h-2 border-b border-r border-white/30 rounded-br-xl pointer-events-none group-focus-within/input:border-success"></div>
          </div>
        </div>

        {/* Quick Add Presets */}
        <div className="mt-10 relative z-10">
          <div className="flex items-center gap-2 mb-4">
             <span className="material-symbols-outlined text-success text-sm">bolt</span>
             <p className="text-xs text-text-muted font-mono tracking-widest uppercase">Quick Injection</p>
          </div>
          <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-3">
            {presets.map((preset) => (
              <button
                key={preset.label}
                onClick={() => addMoney(preset.value)}
                className="bg-surface border border-white/5 text-text-muted text-sm font-mono tracking-wider 
                           py-3 px-4 rounded-lg hover:border-success/50 hover:text-success hover:bg-success/10
                           transition-all duration-300 cursor-pointer active:scale-95 text-center flex flex-col items-center gap-1 group/btn"
              >
                <span className="material-symbols-outlined text-[16px] opacity-0 h-0 group-hover/btn:opacity-100 group-hover/btn:h-auto transition-all">add_circle</span>
                {preset.label}
              </button>
            ))}
          </div>
        </div>
      </div>

      {/* Info card Terminal Style */}
      <div className="bg-surface-dark border border-warning/30 rounded-xl p-5 flex items-start gap-4 shadow-[0_0_15px_rgba(234,179,8,0.05)] relative overflow-hidden">
        <div className="absolute top-0 left-0 w-1 h-full bg-warning"></div>
        <span className="material-symbols-outlined text-warning text-2xl mt-0.5 animate-pulse">warning</span>
        <div>
           <p className="text-warning font-mono text-xs tracking-widest uppercase mb-1">System Warning</p>
           <p className="text-sm text-text-muted font-body leading-relaxed">
             Uang akan langsung berubah saat memuat save file. Disarankan tidak melebihi <span className="text-warning font-mono bg-warning/10 px-1.5 py-0.5 rounded border border-warning/20">999.999.999</span> untuk mencegah overflow.
           </p>
        </div>
      </div>
    </div>
  );
}
